use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encodes every byte outside the RFC 3986 unreserved set, so that
/// adversarial item text cannot add query parameters, fragments, or path
/// segments to the enrichment URL.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(hex_digit(b >> 4));
                out.push(hex_digit(b & 0x0f));
            }
        }
    }
    out
}

fn hex_digit(n: u8) -> char {
    match n {
        0..=9 => (b'0' + n) as char,
        _ => (b'A' + n - 10) as char,
    }
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        let mut kept = Vec::with_capacity(items.len());

        for item in items {
            // Enrichment fetch, once per input item. `fetch` (not `get`) is used
            // so that a transport failure is a value and cannot trap the node.
            // The result is deliberately discarded: the node's output is
            // unchanged by enrichment.
            let url = format!("{}{}", ENRICH_BASE, percent_encode(&item.text));
            let _ = http_client::fetch(&url);

            // Drop items already recorded in the `seen` store. The store is
            // keyed by the parser-computed item id.
            match state_read::get(&item.id) {
                Some(_) => {}
                None => kept.push(item),
            }
        }

        kept
    }
}

export!(Node);
```

